    private static readonly FrozenDictionary<string, MetricFieldDefinition> ByTemplate =
        BaseDefinitions.ToFrozenDictionary(static field => field.RequestTemplate, StringComparer.Ordinal);
    public static IReadOnlyList<MetricFieldDefinition> Definitions { get; } = BaseDefinitions
        .Concat(new[] { "nvidia.nvml", "amd.adlx", "amd.smu" }.SelectMany(source => BaseDefinitions
            .Select(field => FindByTemplate(field.RequestTemplate, source)!)))
        .DistinctBy(static field => field.Name).ToArray();
    private static readonly FrozenDictionary<string, MetricFieldDefinition> ByName =
        Definitions.ToFrozenDictionary(static field => field.Name, StringComparer.Ordinal);
    private static readonly FrozenDictionary<string, string> PublicNameAliases = new Dictionary<string, string>(StringComparer.Ordinal)
    {
        ["fan_all_rotational_speed"] = "fan_all_speed_rpm",
        ["fan_all_pwm_reported"] = "fan_all_reported_pwm_duty"
    }.ToFrozenDictionary(StringComparer.Ordinal);
    public static string NormalizePublicName(string name)
        => PublicNameAliases.GetValueOrDefault(name, name);
    internal static IEnumerable<string> PublicNamesOf(string canonicalName)
        => PublicNameAliases.Where(pair => pair.Value == canonicalName)
            .Select(static pair => pair.Key).Prepend(canonicalName);
    public static MetricFieldDefinition? FindByName(string name)
        => ByName.GetValueOrDefault(NormalizePublicName(name));
    public static MetricFieldDefinition? FindByTemplate(string template, string? sourceId = null)
    {
        var field = ByTemplate.GetValueOrDefault(template);
        if (field is null) return null;
        return (field.Code, sourceId) switch
        {
            (MetricFieldCode.CpuTemperature, "amd.smu") => field with { Name = "cpu_amd_smu_temperature_reported_celsius", Vendor = MetricVendor.Amd },
            (MetricFieldCode.GpuUsage, "nvidia.nvml") => field with { Name = "gpu_nvidia_processor_busy_percent", Vendor = MetricVendor.Nvidia },
            (MetricFieldCode.GpuUsage, "amd.adlx") => field with { Name = "gpu_amd_activity_percent", Vendor = MetricVendor.Amd },
            (MetricFieldCode.GpuTemperature, "amd.adlx") => field with { Name = "gpu_amd_edge_temperature_celsius", Vendor = MetricVendor.Amd },
            (MetricFieldCode.GpuTemperature, "nvidia.nvml") => field with { Name = "gpu_nvidia_core_temperature_celsius", Vendor = MetricVendor.Nvidia },
            (MetricFieldCode.GpuTemperature, "amd.smu") => field with { Name = "gpu_amd_apu_temperature_reported_celsius", Vendor = MetricVendor.Amd, HasLegacyAddress = false },
            (MetricFieldCode.GpuMemoryTemperature, "nvidia.nvml") => field with { Name = "gpu_nvidia_memory_temperature_celsius", Vendor = MetricVendor.Nvidia },
            (MetricFieldCode.GpuMemoryTemperature, "amd.adlx") => field with { Name = "gpu_amd_memory_temperature_celsius", Vendor = MetricVendor.Amd },
            (MetricFieldCode.GpuMemoryUsed, "nvidia.nvml") => field with { Name = "gpu_nvidia_fb_used_v1_including_reserved_bytes", Vendor = MetricVendor.Nvidia },
            (MetricFieldCode.GpuMemoryTotal, "nvidia.nvml") => field with { Name = "gpu_nvidia_fb_total_bytes", Vendor = MetricVendor.Nvidia },
            (MetricFieldCode.GpuMemoryUsed, "amd.adlx") => field with { Name = "gpu_amd_vram_used_reported_bytes", Vendor = MetricVendor.Amd },
            (MetricFieldCode.GpuMemoryPercent, "nvidia.nvml") => field with { Name = "gpu_nvidia_fb_used_v1_including_reserved_percent", Vendor = MetricVendor.Nvidia },
            (MetricFieldCode.GpuMemoryPercent, "amd.adlx") => field with { Name = "gpu_amd_vram_used_reported_percent", Vendor = MetricVendor.Amd },
            (MetricFieldCode.GpuPower, "nvidia.nvml") => field with { Name = "gpu_nvidia_power_reported_watts", Vendor = MetricVendor.Nvidia },
            (MetricFieldCode.GpuPower, "amd.adlx") => field with { Name = "gpu_amd_chip_power_watts", Vendor = MetricVendor.Amd },
            _ => field
        };
    }
